<?php
/**
 * config/config.php
 * ------------------------------------------------------------------
 * Global settings for the whole application.
 * Every page loads this file (through config/database.php), so the
 * values below are available everywhere.
 *
 * >>> You do NOT edit this file to deploy. The live server gets its own
 * >>> settings file (database password, BASE_URL, debug off):
 * >>>     config/config.production.php   (copy of config.production.example.php)
 * >>> When that file exists it replaces the XAMPP defaults below.
 * >>> It never leaves the server and is never sent to the browser.
 */

// ---------- Defaults for local development (XAMPP) ----------
$settings = [
    'db_host'  => 'localhost',
    'db_name'  => 'event_registration_db',
    'db_user'  => 'root',
    'db_pass'  => '',                      // XAMPP's root user has no password by default
    // URL path to the project folder. Must start and end with "/".
    //   XAMPP: http://localhost/event-registration/ → '/event-registration/'
    'base_url' => '/event-registration/',
    // true = show error details (XAMPP only). Production files set false.
    'debug'    => true,
];

// ---------- Production settings (only present on the live server) ----------
// Looked for in this order; the first file found wins:
//   1. ers-config.php ONE LEVEL ABOVE the project folder — outside htdocs when the
//      project sits directly in htdocs (use it if your host lets you upload there)
//   2. config/config.production.php — inside the project, but the config/ folder
//      is blocked by .htaccess, and the file only returns an array (prints nothing)
// "@" hides the warning some hosts give when PHP may not look outside htdocs.
foreach ([dirname(__DIR__, 2) . '/ers-config.php', __DIR__ . '/config.production.php'] as $settingsFile) {
    if (@is_file($settingsFile)) {
        $settings = array_merge($settings, (array) require $settingsFile);
        break;
    }
}

define('DB_HOST', (string) $settings['db_host']);
define('DB_NAME', (string) $settings['db_name']);
define('DB_USER', (string) $settings['db_user']);
define('DB_PASS', (string) $settings['db_pass']);
define('DB_CHARSET', 'utf8mb4');

// ---------- Application settings ----------
define('APP_NAME', 'CICI Event Registration');
define('ORG_NAME', 'College of Informatics and Computing Innovations');
define('UNIVERSITY_NAME', 'Iloilo State University of Fisheries Science and Technology');
define('UNIVERSITY_URL', 'https://isufst.edu.ph/');
// Always "/" or "/folder/" — forgiving if the settings file leaves out a slash
$basePath = trim((string) $settings['base_url'], '/');
define('BASE_URL', $basePath === '' ? '/' : '/' . $basePath . '/');

// true  = show detailed errors (XAMPP)
// false = hide details from visitors (live site)
define('APP_DEBUG', (bool) $settings['debug']);
unset($settings, $settingsFile, $basePath);

// ---------- PHP settings ----------
date_default_timezone_set('Asia/Manila');

// Always LOG every error (to the server's error log); only SHOW them while debugging.
error_reporting(E_ALL);
ini_set('log_errors', '1');
ini_set('display_errors', APP_DEBUG ? '1' : '0');

// Basic security headers for every page:
//   X-Frame-Options        → other sites cannot show our pages in a frame (stops "clickjacking"
//                            tricks that make an admin click Delete without knowing)
//   X-Content-Type-Options → browsers must not guess file types
//   Referrer-Policy        → don't send our URLs (with ids/search terms) to other sites
if (!headers_sent()) {
    header('X-Frame-Options: SAMEORIGIN');
    header('X-Content-Type-Options: nosniff');
    header('Referrer-Policy: same-origin');
}

// Start the session once for every page (used later for admin login
// and flash messages). Must happen before any HTML is printed.
if (session_status() === PHP_SESSION_NONE) {
    // Harden the session cookie before starting the session:
    //   httponly  → JavaScript cannot read the cookie (limits XSS damage)
    //   samesite  → browser does not send it on cross-site POSTs
    //   secure    → only sent over HTTPS (turned on automatically on HTTPS hosts such as InfinityFree)
    //   strict mode → PHP refuses session IDs it did not create (stops session fixation)
    $isHttps = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off')
        || (($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https');
    ini_set('session.use_strict_mode', '1');
    ini_set('session.use_only_cookies', '1');
    session_set_cookie_params([
        'lifetime' => 0,            // until the browser closes
        'path'     => BASE_URL,
        'secure'   => $isHttps,
        'httponly' => true,
        'samesite' => 'Lax',
    ]);
    session_name('ERS_SESSION');
    session_start();
}

// Admin session ends after this many seconds without activity.
define('ADMIN_IDLE_TIMEOUT', 30 * 60);

// Load small helper functions used across the project.
require_once __DIR__ . '/../includes/functions.php';

// Any error nobody caught (e.g. the database stops answering in the middle
// of a page) shows a friendly page with HTTP 500 instead of a PHP stack trace.
set_exception_handler('show_fatal_error');
